/bin/bash -lc "python - <<'PY'
import inspect
try:
 from bioblend.galaxy import GalaxyInstance
 from bioblend.galaxy.histories import HistoryClient
 print('bioblend yes')
 print('methods', [x for x in dir(HistoryClient) if 'copy' in x or 'clone' in x])
 for x in dir(HistoryClient):
  if 'copy' in x or 'clone' in x:
   print(x, inspect.signature(getattr(HistoryClient,x)))
except Exception as e:
 print(type(e).__name__, str(e))
PY"

